   473	Guchar *ImageStream::getLine() {
   474	  if (unlikely(inputLine == nullptr)) {
   475	      return nullptr;
   476	  }
   477	 
   478	  int readChars = str->doGetChars(inputLineSize, inputLine);
   479	  for ( ; readChars < inputLineSize; readChars++) inputLine[readChars] = EOF;
   480	  if (nBits == 1) {
   481	    Guchar *p = inputLine;
   482	    for (int i = 0; i < nVals; i += 8) {
   483	      const int c = *p++;
   484	      imgLine[i+0] = (Guchar)((c >> 7) & 1);
   485	      imgLine[i+1] = (Guchar)((c >> 6) & 1);
   486	      imgLine[i+2] = (Guchar)((c >> 5) & 1);
   487	      imgLine[i+3] = (Guchar)((c >> 4) & 1);
   488	      imgLine[i+4] = (Guchar)((c >> 3) & 1);
   489	      imgLine[i+5] = (Guchar)((c >> 2) & 1);
   490	      imgLine[i+6] = (Guchar)((c >> 1) & 1);
   491	      imgLine[i+7] = (Guchar)(c & 1);
   492	    }
   493	  } else if (nBits == 8) {
   494	    // special case: imgLine == inputLine
   495	  } else if (nBits == 16) {
   496	    // this is a hack to support 16 bits images, everywhere
   497	    // we assume a component fits in 8 bits, with this hack
   498	    // we treat 16 bit images as 8 bit ones until it's fixed correctly.
   499	    // The hack has another part on GfxImageColorMap::GfxImageColorMap
   500	    Guchar *p = inputLine;
   501	    for (int i = 0; i < nVals; ++i) {
   502	      imgLine[i] = *p++;
   503	      p++;
   504	    }
   505	  } else {
   506	    const Gulong bitMask = (1 << nBits) - 1;
   507	    Gulong buf = 0;
   508	    int bits = 0;
   509	    Guchar *p = inputLine;
   510	    for (int i = 0; i < nVals; ++i) {
   511	      while (bits < nBits) {
   512	        buf = (buf << 8) | (*p++ & 0xff);
   513	        bits += 8;
   514	      }
   515	      imgLine[i] = (Guchar)((buf >> (bits - nBits)) & bitMask);
   516	      bits -= nBits;
   517	    }
   518	  }
   519	  return imgLine;
   520	}
