    52	UnicodeMap *UnicodeMap::parse(GooString *encodingNameA) {
    53	  FILE *f;
    54	  UnicodeMap *map;
    55	  UnicodeMapRange *range;
    56	  UnicodeMapExt *eMap;
    57	  int size, eMapsSize;
    58	  char buf[256];
    59	  int line, nBytes, i;
    60	  char *tok1, *tok2, *tok3;
    61	  char *tokptr;
    62	
    63	  if (!(f = globalParams->getUnicodeMapFile(encodingNameA))) {
    64	    error(errSyntaxError, -1,
    65	          "Couldn't find unicodeMap file for the '{0:t}' encoding",
    66	          encodingNameA);
    67	    return nullptr;
    68	  }
    69	
    70	  map = new UnicodeMap(encodingNameA->copy());
    71	
    72	  size = 8;
    73	  map->ranges = (UnicodeMapRange *)gmallocn(size, sizeof(UnicodeMapRange));
    74	  eMapsSize = 0;
    75	
    76	  line = 1;
    77	  while (getLine(buf, sizeof(buf), f)) {
    78	    if ((tok1 = strtok_r(buf, " \t\r\n", &tokptr)) &&
    79	        (tok2 = strtok_r(nullptr, " \t\r\n", &tokptr))) {
    80	      if (!(tok3 = strtok_r(nullptr, " \t\r\n", &tokptr))) {
    81	        tok3 = tok2;
    82	        tok2 = tok1;
    83	      }
    84	      nBytes = strlen(tok3) / 2;
    85	      if (nBytes <= 4) {
    86	        if (map->len == size) {
    87	          size *= 2;
    88	          map->ranges = (UnicodeMapRange *)
    89	            greallocn(map->ranges, size, sizeof(UnicodeMapRange));
    90	        }
    91	        range = &map->ranges[map->len];
    92	        sscanf(tok1, "%x", &range->start);
    93	        sscanf(tok2, "%x", &range->end);
    94	        sscanf(tok3, "%x", &range->code);
    95	        range->nBytes = nBytes;
    96	        ++map->len;
    97	      } else if (tok2 == tok1) {
    98	        if (map->eMapsLen == eMapsSize) {
    99	          eMapsSize += 16;
   100	          map->eMaps = (UnicodeMapExt *)
   101	            greallocn(map->eMaps, eMapsSize, sizeof(UnicodeMapExt));
   102	        }
   103	        eMap = &map->eMaps[map->eMapsLen];
   104	        sscanf(tok1, "%x", &eMap->u);
   105	        for (i = 0; i < nBytes; ++i) {
   106	          unsigned int x;
   107	          sscanf(tok3 + i*2, "%2x", &x);
   108	          eMap->code[i] = (char)x;
   109	        }
   110	        eMap->nBytes = nBytes;
   111	        ++map->eMapsLen;
   112	      } else {
   113	        error(errSyntaxError, -1,
   114	              "Bad line ({0:d}) in unicodeMap file for the '{1:t}' encoding",
   115	              line, encodingNameA);
   116	      }
   117	    } else {
   118	      error(errSyntaxError, -1,
   119	            "Bad line ({0:d}) in unicodeMap file for the '{1:t}' encoding",
   120	            line, encodingNameA);
   121	    }
   122	    ++line;
   123	  }
   124	
   125	  fclose(f);
   126	
   127	  return map;
   128	}
