   328	
   329	UnicodeMap *UnicodeMapCache::getUnicodeMap(GooString *encodingName) {
   330	  UnicodeMap *map;
   331	  int i, j;
   332	
   333	  if (cache[0] && cache[0]->match(encodingName)) {
   334	    cache[0]->incRefCnt();
   335	    return cache[0];
   336	  }
   337	  for (i = 1; i < unicodeMapCacheSize; ++i) {
   338	    if (cache[i] && cache[i]->match(encodingName)) {
   339	      map = cache[i];
   340	      for (j = i; j >= 1; --j) {
   341	        cache[j] = cache[j - 1];
   342	      }
   343	      cache[0] = map;
   344	      map->incRefCnt();
   345	      return map;
   346	    }
   347	  }
   348	  if ((map = UnicodeMap::parse(encodingName))) {
   349	    if (cache[unicodeMapCacheSize - 1]) {
   350	      cache[unicodeMapCacheSize - 1]->decRefCnt();
   351	    }
   352	    for (j = unicodeMapCacheSize - 1; j >= 1; --j) {
   353	      cache[j] = cache[j - 1];
   354	    }
   355	    cache[0] = map;
   356	    map->incRefCnt();
   357	    return map;
   358	  }
   359	  return nullptr;
   360	}
